// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    // fuzzed caller address; for the correct contract, only the owner can call owned() successfully.
    function testFuzz_property(address caller) public {
        // keep wide domain but avoid zero address triviality (owner may be zero initially)
        vm.assume(caller != address(0));

        // determine current owner
        address currentOwner = c.owner();

        bool ok;
        // make the call as `caller` and record whether it succeeds (does not revert)
        vm.prank(caller);
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: only the owner may successfully call owned(); i.e., ok == (caller == currentOwner)
        // This holds for the reference contract for all inputs; the mutant (which removes onlyOwner) will
        // allow ok == true for some caller != currentOwner, causing this assertion to fail.
        assertTrue(ok == (caller == currentOwner));
    }
}
